        // Cargo: badges, KPIs numéricos y nombres propios (EN = ES cuando ya son en inglés)
        "Operaciones": "Operations",
        "Visión 2028-2030": "Vision 2028-2030",
        "+1.5 a 3.0 Ton": "+1.5 to 3.0 Ton",
        "+4.0% a +6.5%": "+4.0% to +6.5%",
        "-30% a -42%": "-30% to -42%",
        "< 90 seg": "< 90 sec",
        "Compliance": "Compliance",
        "Tracking & CX": "Tracking & CX",
        "The Autonomous Air Cargo Network": "The Autonomous Air Cargo Network",
        "Lufthansa Cargo": "Lufthansa Cargo",
        "Qatar Airways Cargo": "Qatar Airways Cargo",
        "Delta Cargo": "Delta Cargo",
        "CargoQuote Dynamic Engine": "CargoQuote Dynamic Engine",
        "Neuro-Overbooking Optimizer": "Neuro-Overbooking Optimizer",
        "BellyYield Auto-Disrupter": "BellyYield Auto-Disrupter",
        "Autonomous ULD Fleet Allocator & 3D Load Planner": "Autonomous ULD Fleet Allocator & 3D Load Planner",
        "ColdChain Sentinel & Disruption Handler": "ColdChain Sentinel & Disruption Handler",
        "CargoCare Cognitive Orchestrator": "CargoCare Cognitive Orchestrator",
